def _polygon_fully_inside_mask(points: np.ndarray, bubble_mask: np.ndarray) -> bool:
    if points is None or points.size == 0 or bubble_mask is None:
        return False
    h, w = bubble_mask.shape[:2]
    if h <= 0 or w <= 0:
        return False

    pts = np.asarray(points, dtype=np.int32)
    if pts.ndim != 2 or pts.shape[0] < 3:
        return False
    pts[:, 0] = np.clip(pts[:, 0], 0, max(w - 1, 0))
    pts[:, 1] = np.clip(pts[:, 1], 0, max(h - 1, 0))

    # Node Comics: keep upstream clipping/rasterization, but inspect only the ROI.
    x, y, width, height = cv2.boundingRect(pts)
    poly_mask = np.zeros((height, width), dtype=np.uint8)
    cv2.fillPoly(poly_mask, [pts - np.array([x, y], dtype=np.int32)], 255)
    poly_pixels = poly_mask > 0
    if not np.any(poly_pixels):
        return False
    return bool(np.all(bubble_mask[y:y + height, x:x + width][poly_pixels] > 0))
